from pathlib import Path
code = '''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    row_divs = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    col_divs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def ranges(n, divs):
        out = []
        start = 0
        for d in divs:
            out.append((start, d))
            start = d + 1
        out.append((start, n))
        return out

    rs, cs = ranges(h, row_divs), ranges(w, col_divs)
    blocks = []
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != bg]
            if cells:
                blocks.append((len(cells), ri, ci, cells))
    _, sri, sci, pattern = max(blocks, key=lambda x: x[0])

    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            for dr, dc, value in pattern:
                if dr < r1-r0 and dc < c1-c0:
                    out[r0+dr][c0+dc] = value
    return out
'''
